      await expect(page.getByText("Todo")).toBeVisible({ timeout: 10000 });
    });

    test("displays timestamps", async ({ page }) => {
      await page.goto(`/issues/${testIssueId}`);
      await expect(page.getByText(/Created/)).toBeVisible({ timeout: 10000 });
      await expect(page.getByText(/Updated/)).toBeVisible({ timeout: 10000 });
    });

    test("displays tags", async ({ page }) => {
      await page.goto(`/issues/${testIssueId}`);
      await expect(page.getByText("e2e")).toBeVisible({ timeout: 10000 });
      await expect(page.getByText("detail")).toBeVisible({ timeout: 10000 });
    });

    test("inline edit title", async ({ page }) => {
      await page.goto(`/issues/${testIssueId}`);
      await page.waitForLoadState("networkidle");

      // Click on the title to enter edit mode
      const titleEl = page.getByText("Phase2 E2E: Detail page test");
      await titleEl.click();

      // An input should appear
      const titleInput = page.locator('input.text-xl');
      await expect(titleInput).toBeVisible({ timeout: 5000 });

      // Clear and type new title
      await titleInput.clear();
      await titleInput.fill("Phase2 E2E: Updated title");

      // Press Enter to save
      await titleInput.press("Enter");

      // Verify the title was updated
      await expect(
        page.getByText("Phase2 E2E: Updated title")
      ).toBeVisible({ timeout: 10000 });

      // Verify via API
      const apiIssue = await page.evaluate(async (id) => {
        const res = await fetch(`/api/issues/${id}`);
        return res.json();
      }, testIssueId);
      expect(apiIssue.title).toBe("Phase2 E2E: Updated title");
    });

    test("inline edit description", async ({ page }) => {
      await page.goto(`/issues/${testIssueId}`);
      await page.waitForLoadState("networkidle");

      // Click on the description area to enter edit mode
      const descArea = page.getByText("Testing detail page features");
      await descArea.click();

      // A textarea should appear
      const textarea = page.locator("textarea").filter({ hasText: "Testing detail page features" });
      await expect(textarea).toBeVisible({ timeout: 5000 });

      // Clear and type new description
      await textarea.clear();
      await textarea.fill("Updated description via E2E test");

      // Click Save button
      await page.locator("button").filter({ hasText: "Save" }).click();

      // Verify the new description appears
      await expect(
        page.getByText("Updated description via E2E test")
      ).toBeVisible({ timeout: 10000 });
    });

    test("change status via dropdown", async ({ page }) => {
      await page.goto(`/issues/${testIssueId}`);
      await page.waitForLoadState("networkidle");

      // Find the status dropdown trigger (next to "Status:" label)
      // Click on the status select trigger
      const statusSection = page.locator("text=Status:").locator("..");
      const statusTrigger = statusSection.locator("button").first();
      await statusTrigger.click();

      // Select "In Progress" option
      const inProgressOption = page.locator("[role='option']").filter({ hasText: "In Progress" });
      await inProgressOption.click();

      // Wait for update
      await page.waitForTimeout(1000);

      // Verify via API
      const apiIssue = await page.evaluate(async (id) => {
        const res = await fetch(`/api/issues/${id}`);
        return res.json();
      }, testIssueId);
      expect(apiIssue.status).toBe("in-progress");
    });

    test("change priority via dropdown", async ({ page }) => {
      await page.goto(`/issues/${testIssueId}`);
      await page.waitForLoadState("networkidle");

      // Find the priority dropdown
      const prioritySection = page.locator("text=Priority:").locator("..");
      const priorityTrigger = prioritySection.locator("button").first();
      await priorityTrigger.click();

      // Select P5
      const p5Option = page.locator("[role='option']").filter({ hasText: "P5" });
      await p5Option.click();

      await page.waitForTimeout(1000);

      // Verify via API
      const apiIssue = await page.evaluate(async (id) => {
        const res = await fetch(`/api/issues/${id}`);
        return res.json();
      }, testIssueId);
      expect(apiIssue.priority).toBe(5);
    });
  });
});

