      }, testIssueId);
      expect(apiIssue.title).toBe("Title Edit Test Updated");
    });

    test("inline edit description", async ({ page, request }) => {
      const res = await request.post("http://localhost:3000/api/issues", {
        data: {
          title: "Desc Edit Test",
          description: "Original description for editing",
        },
      });
      const { id: testIssueId } = await res.json();

      await page.goto(`/issues/${testIssueId}`);
      await page.waitForLoadState("networkidle");

      // Click on the description area to enter edit mode
      const descArea = page.getByText("Original description for editing");
      await descArea.click();

      // A textarea should appear
