    test("change status via dropdown", async ({ page, request }) => {
      const res = await request.post("http://localhost:3000/api/issues", {
        data: { title: "Status Change Test", status: "todo" },
      });
      const { id: testIssueId } = await res.json();

      await page.goto(`/issues/${testIssueId}`);
      await page.waitForLoadState("networkidle");

      // Find the status dropdown trigger (next to "Status:" label)
      const statusLabel = page.getByText("Status:", { exact: false }).first();
      const statusRow = statusLabel.locator("..");
      const statusTrigger = statusRow.locator("button").first();
      await statusTrigger.click();

      // Select "In Progress" option
      const inProgressOption = page
        .locator("[role='option']")
        .filter({ hasText: "In Progress" });
      await inProgressOption.click();

      // Wait for update to complete
      await page.waitForResponse(
        (resp) => resp.url().includes(`/api/issues/${testIssueId}`) && resp.status() === 200,
        { timeout: 10000 }
      );

      // Verify via API
      const apiIssue = await page.evaluate(async (id) => {
        const res = await fetch(`/api/issues/${id}`);
        return res.json();
      }, testIssueId);
      expect(apiIssue.status).toBe("in-progress");
    });

    test("change priority via dropdown", async ({ page, request }) => {
      const res = await request.post("http://localhost:3000/api/issues", {
        data: { title: "Priority Change Test", priority: 3 },
      });
      const { id: testIssueId } = await res.json();

      await page.goto(`/issues/${testIssueId}`);
      await page.waitForLoadState("networkidle");

      // Find the priority dropdown
      const priorityLabel = page.getByText("Priority:", { exact: false }).first();
      const priorityRow = priorityLabel.locator("..");
      const priorityTrigger = priorityRow.locator("button").first();
      await priorityTrigger.click();

      // Select P5
      const p5Option = page
        .locator("[role='option']")
        .filter({ hasText: "P5" });
      await p5Option.click();

      // Wait for update to complete
      await page.waitForResponse(
        (resp) => resp.url().includes(`/api/issues/${testIssueId}`) && resp.status() === 200,
        { timeout: 10000 }
      );

      // Verify via API
      const apiIssue = await page.evaluate(async (id) => {
        const res = await fetch(`/api/issues/${id}`);
        return res.json();
      }, testIssueId);
      expect(apiIssue.priority).toBe(5);
    });

    test("change assignee via dropdown", async ({ page, request }) => {
      const res = await request.post("http://localhost:3000/api/issues", {
        data: { title: "Assignee Change Test", assignee: null },
      });
      const { id: testIssueId } = await res.json();

      await page.goto(`/issues/${testIssueId}`);
      await page.waitForLoadState("networkidle");

      // Find the assignee dropdown
      const assigneeLabel = page.getByText("Assignee:", { exact: false }).first();
      const assigneeRow = assigneeLabel.locator("..");
      const assigneeTrigger = assigneeRow.locator("button").first();
      await assigneeTrigger.click();

      // Select the first real user option (not "Unassigned")
      const userOptions = page
        .locator("[role='option']")
        .filter({ hasNotText: "Unassigned" });
      const firstUser = userOptions.first();
      if (await firstUser.isVisible()) {
        const userName = await firstUser.textContent();
        await firstUser.click();

        // Wait for update to complete
        await page.waitForResponse(
          (resp) =>
            resp.url().includes(`/api/issues/${testIssueId}`) &&
            resp.status() === 200,
          { timeout: 10000 }
        );

        // Verify via API
        const apiIssue = await page.evaluate(async (id) => {
          const res = await fetch(`/api/issues/${id}`);
          return res.json();
        }, testIssueId);
        expect(apiIssue.assignee).toBe(userName?.trim());
      }
    });
  });
});

