  // ─── Frontend: Issue Detail Page ────────────────────────────────────

  test.describe("Frontend: Issue Detail Page", () => {
    test("displays issue title and ID", async ({ page, request }) => {
      // Create a fresh issue for this test
      const res = await request.post("http://localhost:3000/api/issues", {
        data: {
          title: "Detail Display Test",
          description: "Testing detail page display",
          status: "todo",
          priority: 2,
          tags: ["display-test"],
          assignee: "test-bot",
