    test("displays status badge", async ({ page, request }) => {
      const res = await request.post("http://localhost:3000/api/issues", {
        data: { title: "Status Badge Test", status: "todo" },
      });
      const { id: testIssueId } = await res.json();

      await page.goto(`/issues/${testIssueId}`);
      // "Todo" appears in the badge — filter to exact match
