      await expect(page.getByText(/Updated/)).toBeVisible({ timeout: 10000 });
    });

    test("displays tags", async ({ page, request }) => {
      const res = await request.post("http://localhost:3000/api/issues", {
        data: {
          title: "Tag Display Test",
          tags: ["unique-tag-display-test"],
        },
      });
      const { id: testIssueId } = await res.json();

      await page.goto(`/issues/${testIssueId}`);
      await expect(
        page.getByText("unique-tag-display-test")
      ).toBeVisible({ timeout: 10000 });
    });

    test("inline edit title", async ({ page, request }) => {
      const res = await request.post("http://localhost:3000/api/issues", {
        data: { title: "Title Edit Test Original" },
